// === VALIDAÇÃO + DEDUP ===
const item = $input.first();
const body = item.json.body || item.json;

const event = body.event;
const data = body.data || body;

// 1. Ignorar se não for evento de mensagem
if (event && event !== 'message') {
  return [];
}

// 2. Ignorar mensagens próprias (enviadas pelo bot)
if (data.fromMe === true) {
  return [];
}

// 3. Ignorar mensagens de grupo
if (data.isGroup === true) {
  return [];
}

// 4. Ignorar se não tiver remetente
const from = data.from || data.remoteJid || '';
if (!from || from.length < 10) {
  return [];
}

// 5. Ignorar status updates (broadcast)
if (from.includes('status@broadcast') || from.includes('@g.us')) {
  return [];
}

// 6. Dedup: verificar se essa msg já foi processada (pelo ID)
const msgId = data.id || data.key?.id || '';
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedMsgs) staticData.processedMsgs = {};

// Limpar msgs antigas (mais de 5 min)
const now = Date.now();
for (const [key, ts] of Object.entries(staticData.processedMsgs)) {
  if (now - ts > 300000) delete staticData.processedMsgs[key];
}

if (msgId && staticData.processedMsgs[msgId]) {
  return []; // Duplicata
}
if (msgId) staticData.processedMsgs[msgId] = now;

// 7. Normalizar número (remover sufixo @s.whatsapp.net)
const whatsappNumber = from.replace('@s.whatsapp.net', '').replace('@c.us', '');

// 8. Determinar tipo e conteúdo
const msgType = (data.type || 'text').toLowerCase();
let content = data.body || data.text || '';
const mediaUrl = data.mediaUrl || data.base64 || '';
const pushName = data.pushName || data.notifyName || '';
const timestamp = data.timestamp || Math.floor(Date.now() / 1000);

// Marcar tipo para tratamento multimodal
if (msgType === 'audio' || msgType === 'ptt') {
  content = content || '[Áudio recebido - transcrição não disponível]';
}
if (msgType === 'image' || msgType === 'sticker') {
  content = content || '[Imagem recebida]';
}
if (msgType === 'video') {
  content = content || '[Vídeo recebido]';
}
if (msgType === 'document') {
  content = content || '[Documento recebido]';
}

// Se não tem conteúdo nenhum, ignorar
if (!content.trim()) {
  return [];
}

return [{
  json: {
    whatsapp_number: whatsappNumber,
    content: content.trim(),
    type: msgType,
    media_url: mediaUrl,
    profile_name: pushName,
    meta_message_id: msgId,
    timestamp: timestamp,
    raw_event: event
  }
}];

// === BUFFER DE MENSAGENS PICOTADAS ===
// Aguarda 4s de silêncio antes de consolidar mensagens do mesmo remetente

const item = $input.first();
const data = item.json;
const number = data.whatsapp_number;

const staticData = $getWorkflowStaticData('global');
if (!staticData.msgBuffer) staticData.msgBuffer = {};

const now = Date.now();

// Se já tem buffer para esse número
if (staticData.msgBuffer[number]) {
  const buf = staticData.msgBuffer[number];
  buf.messages.push(data.content);
  buf.lastTimestamp = now;
  buf.profile_name = data.profile_name || buf.profile_name;
  buf.type = data.type;
  buf.meta_message_id = data.meta_message_id;

  // Checar se é hora de consolidar (4s desde a última msg)
  const timeSinceLast = now - buf.createdAt;
  if (timeSinceLast < 4000) {
    // Ainda dentro da janela, esperar mais
    return [];
  }

  // Consolidar e limpar buffer
  const consolidated = buf.messages.join('\n');
  delete staticData.msgBuffer[number];

  return [{
    json: {
      whatsapp_number: number,
      content: consolidated,
      type: buf.type,
      profile_name: buf.profile_name,
      meta_message_id: buf.meta_message_id,
      timestamp: Math.floor(now / 1000),
      is_consolidated: true,
      message_count: buf.messages.length
    }
  }];
} else {
  // Primeira msg desse número - criar buffer e processar imediatamente
  // (Na prática, o buffer funciona melhor com Wait node, mas para simplificar
  //  processamos a primeira msg e buffamos subsequentes dentro de 4s)
  staticData.msgBuffer[number] = {
    messages: [],
    createdAt: now,
    lastTimestamp: now,
    profile_name: data.profile_name,
    type: data.type,
    meta_message_id: data.meta_message_id
  };

  // Agendar limpeza do buffer em 5s (safety net)
  setTimeout(() => {
    if (staticData.msgBuffer && staticData.msgBuffer[number]) {
      delete staticData.msgBuffer[number];
    }
  }, 5000);

  return [{
    json: {
      whatsapp_number: number,
      content: data.content,
      type: data.type,
      profile_name: data.profile_name,
      meta_message_id: data.meta_message_id,
      timestamp: data.timestamp,
      is_consolidated: false,
      message_count: 1
    }
  }];
}

// === CHECAR SE BOT PODE RESPONDER ===
const statusResp = $input.first().json;
const bufferData = $node['04 — Buffer Mensagens Picotadas'].json;

// Extrair dados da resposta da API
const conversationStatus = statusResp.status || statusResp.data?.status || 'BOT';
const botMsgCount = statusResp.bot_message_count || statusResp.data?.bot_message_count || 0;
const conversationId = statusResp.conversation_id || statusResp.data?.conversation_id || null;
const leadId = statusResp.lead_id || statusResp.data?.lead_id || null;

// Se conversa está em atendimento humano, ignorar
if (conversationStatus === 'EM_ATENDIMENTO' || conversationStatus === 'AGUARDANDO_HUMANO') {
  return [];
}

// Anti-loop: se bot já enviou 10+ msgs, forçar handoff
const forceHandoff = botMsgCount >= 10;

return [{
  json: {
    whatsapp_number: bufferData.whatsapp_number,
    content: bufferData.content,
    type: bufferData.type,
    profile_name: bufferData.profile_name,
    meta_message_id: bufferData.meta_message_id,
    conversation_status: conversationStatus,
    conversation_id: conversationId,
    lead_id: leadId,
    bot_message_count: botMsgCount,
    force_handoff: forceHandoff
  }
}];

