const claudeResponse = $input.first().json;
const prep = $node['09 \u2014 Preparar Payload IA'].json;

const hasContent = claudeResponse.content
    && Array.isArray(claudeResponse.content)
    && claudeResponse.content.length > 0
    && claudeResponse.content[0]?.text;

if (hasContent) {
    const text = claudeResponse.content[0].text;
    return [{
        json: {
            choices: [{ message: { content: text } }],
            _source: 'claude',
            _model: claudeResponse.model || 'claude-sonnet-4-20250514'
        }
    }];
}

const errorInfo = claudeResponse.error?.message
    || claudeResponse.statusMessage
    || JSON.stringify(claudeResponse).substring(0, 200);

console.error('Claude falhou:', errorInfo);

return [{
    json: {
        _needs_fallback: true,
        _claude_error: errorInfo,
        openaiPayload: prep.openaiPayload,
        whatsapp_number: prep.whatsapp_number,
        profile_name: prep.profile_name,
        content: prep.content,
        chat_state: prep.chat_state,
        bot_message_count: prep.bot_message_count
    }
}];
